import sqlite3
import os
import hashlib
import time
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        email TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT,
        last_login TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        timestamp TEXT,
        action TEXT,
        details TEXT
    )''')
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('q', '')

    # Validate field name against allowed columns
    allowed_fields = ['username', 'email', 'role', 'last_login']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    if not value:
        return jsonify({'error': 'Query parameter required'}), 400

    # Build query with validated field name but injectable value
    # Note: field is validated above, but value is concatenated
    db = get_db()
    query = f"SELECT id, username, email, role, last_login FROM users WHERE {field} LIKE '%{value}%'"

    try:
        results = db.execute(query).fetchall()
        users = [dict(row) for row in results]
        return jsonify({'users': users, 'count': len(users)})
    except sqlite3.Error as e:
        # Log the error for debugging
        app.logger.error(f"Database error: {e}")
        return jsonify({'error': 'Database error'}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user details by ID."""
    db = get_db()
    user = db.execute(
        'SELECT id, username, email, role, last_login FROM users WHERE id = ?',
        (user_id,)
    ).fetchone()
    if user is None:
        return jsonify({'error': 'User not found'}), 404
    return jsonify(dict(user))

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create a new user account."""
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing required fields'}), 400

    password_hash = hashlib.sha256(data['password'].encode()).hexdigest()
    api_key = hashlib.sha256(os.urandom(32)).hexdigest()

    db = get_db()
    try:
        db.execute(
            'INSERT INTO users (username, password_hash, email, api_key) VALUES (?, ?, ?, ?)',
            (data['username'], password_hash, data.get('email', ''), api_key)
        )
        db.commit()
        return jsonify({'message': 'User created', 'api_key': api_key}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'timestamp': time.time()})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
